package com.truesim.build.publishing

import org.assertj.core.api.Assertions.assertThat
import org.gradle.testkit.runner.GradleRunner
import org.junit.jupiter.api.Test
import java.io.File

/** The POMs `truesim.publishing-conventions` publishes, generated by a small TestKit build. */
class PublishingConventionsTest {

    @Test
    fun `the POM declares the MIT licence`() {
        val dir = File(System.getProperty("truesim.testkit.projects"), "publishing").apply {
            deleteRecursively()
            mkdirs()
        }
        File(dir, "settings.gradle").writeText("rootProject.name = 'publishing'\n")
        File(dir, "build.gradle").writeText(
            """
            |plugins {
            |    id 'java'
            |    id 'truesim.publishing-conventions'
            |}
            |
            |group = 'com.example'
            |version = '1.0.0'
            |""".trimMargin()
        )

        GradleRunner.create()
            .withProjectDir(dir)
            .withPluginClasspath()
            .withArguments("generatePomFileForMavenPublication", "--stacktrace")
            .forwardOutput()
            .build()

        val pom = File(dir, "build/publications/maven/pom-default.xml").readText()
        assertThat(pom).contains(
            "<licenses>",
            "<name>MIT License</name>",
            "<url>https://opensource.org/licenses/MIT</url>"
        )
    }
}
